8	/** Merges multiple async generators into a single async generator that yields values from all of them in parallel. */
9	export async function* mergeAsyncGenerators<T, TReturn>(
10		generators: Gen<T, TReturn>[]
11	): Gen<T, TReturn[]> {
12		const promises: GenPromiseMap<T, TReturn> = new Map();
13		const results: Map<Gen<T, TReturn>, TReturn> = new Map();
14	
15		for (const gen of generators) {
16			promises.set(
17				gen,
18				gen.next().then((result) => ({ gen, ...result }))
19			);
20		}
21	
22		while (promises.size) {
23			const { gen, value, done } = await Promise.race(promises.values());
24			if (done) {
25				results.set(gen, value as TReturn);
26				promises.delete(gen);
27			} else {
28				promises.set(
29					gen,
30					gen.next().then((result) => ({ gen, ...result }))
31				);
32				yield value as T;
33			}
34		}
35	
36		const orderedResults = generators.map((gen) => results.get(gen) as TReturn);
37		return orderedResults;
38	}
